package ma.projet.service; import ma.projet.dao.IDao; import ma.projet.util.HibernateUtil; import org.hibernate.*; import java.util.*; public class GenericService<T> implements IDao<T>{private final Class<T> c; public GenericService(Class<T>x){c=x;} private <R> R go(java.util.function.Function<Session,R> f){try(Session s=HibernateUtil.getSessionFactory().openSession()){Transaction t=s.beginTransaction();try{R r=f.apply(s);t.commit();return r;}catch(RuntimeException e){t.rollback();throw e;}}} public T create(T x){return go(s->{s.persist(x);return x;});} public T update(T x){return go(s->s.merge(x));} public void delete(T x){go(s->{s.remove(s.contains(x)?x:s.merge(x));return null;});} public Optional<T> findById(Long id){try(Session s=HibernateUtil.getSessionFactory().openSession()){return Optional.ofNullable(s.find(c,id));}} public List<T> findAll(){try(Session s=HibernateUtil.getSessionFactory().openSession()){return s.createQuery("from "+c.getSimpleName(),c).list();}}}
